#!/usr/bin/env bash
#
# Unit tests for ../publish-record.sh. Each case builds a small release branch in
# a throwaway git repository, a fake GitHub API holding the commit statuses (see
# ../../guard/tests/fake-gh) and a fake registry index (see fake-curl), then
# runs a snippet against the library and checks what it printed or how it
# failed.
#
# Usage: .github/scripts/crates/tests/test-publish-record.sh
# Requires: bash, git, jq.

# The snippets are single-quoted on purpose: they expand in the shell that runs them.
# shellcheck disable=SC2016

set -uo pipefail

here=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
lib="${here}/../publish-record.sh"
fake_gh="${here}/../../guard/tests/fake-gh"

# The release App's bot, and somebody else who can also post commit statuses.
readonly APP_BOT_ID=187407115
readonly OTHER_ID=4242
readonly CONTEXT="release/crates-published"

failures=0
passes=0

# --- fixture builders --------------------------------------------------------

# A repository on branch stable2609 with nothing in it yet.
new_case() {
	case_dir=$(mktemp -d)
	mkdir -p "${case_dir}/fixtures" "${case_dir}/index" "${case_dir}/bin" "${case_dir}/sha"
	ln -s "$fake_gh" "${case_dir}/bin/gh"
	ln -s "${here}/fake-curl" "${case_dir}/bin/curl"
	: >"${case_dir}/fixtures/calls"
	: >"${case_dir}/index/calls"
	bot_id=$APP_BOT_ID

	git init -q -b stable2609 "${case_dir}/repo"
	git -C "${case_dir}/repo" config user.name "Release Tests"
	git -C "${case_dir}/repo" config user.email "release-tests@example.test"
	git -C "${case_dir}/repo" config commit.gpgsign false
	git -C "${case_dir}/repo" config tag.gpgsign false
}

sha() { # sha <label>
	cat "${case_dir}/sha/$1"
}

keep_sha() { # keep_sha <label>
	git -C "${case_dir}/repo" rev-parse HEAD >"${case_dir}/sha/$1"
}

# A commit that leaves Plan.toml alone.
change() { # change <label>
	git -C "${case_dir}/repo" commit -q --allow-empty -m "$1"
	keep_sha "$1"
}

# A commit with this Plan.toml, in the layout parity-publish writes.
plan() { # plan <label> "<crate> <from> <to>"...
	local label=$1 entry name from to
	shift
	{
		echo "# generated by parity-publish"
		echo
		echo "[options]"
		for entry in "$@"; do
			read -r name from to <<<"$entry"
			printf '\n[[crate]]\n# path/to/%s\nname = "%s"\nfrom = "%s"\nto = "%s"\n' "$name" "$name" "$from" "$to"
			[[ "$from" == "$to" ]] || printf 'bump = "patch"\nreason = "changed"\n'
		done
	} >"${case_dir}/repo/Plan.toml"
	git -C "${case_dir}/repo" add Plan.toml
	git -C "${case_dir}/repo" commit -q --allow-empty -m "$label"
	keep_sha "$label"
}

statuses_path() { # statuses_path <label>
	echo "${case_dir}/fixtures/repos/paritytech/polkadot-sdk/commits/$(sha "$1")/statuses?per_page=100"
}

# Tags a commit, annotated like the signed release tags unless told otherwise.
# The commit gets an empty status list, as the API answers for a commit without
# statuses; a commit that is not tagged has no answer at all, so asking for it
# fails the case.
tag() { # tag <tag name> <label> [lightweight]
	if [[ "${3-}" == lightweight ]]; then
		git -C "${case_dir}/repo" tag "$1" "$(sha "$2")"
	else
		git -C "${case_dir}/repo" tag -a -m "$1" "$1" "$(sha "$2")"
	fi
	local path
	path=$(statuses_path "$2")
	mkdir -p "$(dirname "$path")"
	[[ -f "${path}.json" ]] || echo "[]" >"${path}.json"
}

# The statuses of a commit, newest first as the API lists them.
record() { # record <label> "<status id> <creator id> <state> [context]"...
	local label=$1 json="[]" entry id creator state context path
	shift
	for entry in "$@"; do
		read -r id creator state context <<<"$entry"
		json=$(jq -c --argjson id "$id" --argjson creator "$creator" --arg state "$state" \
			--arg context "${context:-$CONTEXT}" \
			'. + [{id: $id, state: $state, context: $context, creator: {id: $creator}}]' <<<"$json")
	done
	path=$(statuses_path "$label")
	mkdir -p "$(dirname "$path")"
	echo "$json" >"${path}.json"
}

record_error_for() { # record_error_for <label> <stderr text>
	local path
	path=$(statuses_path "$1")
	mkdir -p "$(dirname "$path")"
	echo "$2" >"${path}.error"
}

# The index file of a crate with these versions.
index() { # index <crate> <version>...
	local crate=$1 version
	shift
	for version in "$@"; do
		printf '{"name":"%s","vers":"%s","deps":[],"cksum":"00","features":{},"yanked":false}\n' "$crate" "$version"
	done >"${case_dir}/index/${crate}"
}

index_error() { # index_error <crate> <http status>
	echo "$2" >"${case_dir}/index/$1.code"
}

# A line with one finished release and two rcs of the next:
#   base - p0 (polkadot-stable2609-1) - p1 (-2-rc1) - p2 (-2-rc2) - p3 (tip, not tagged)
patch_line() {
	new_case
	change base
	plan p0 "foo 1.0.0 1.0.1" "bar 2.0.0 2.0.0"
	tag polkadot-stable2609-1-rc1 p0
	tag polkadot-stable2609-1 p0
	plan p1 "foo 1.0.1 1.0.2" "bar 2.0.0 2.0.0"
	tag polkadot-stable2609-2-rc1 p1
	plan p2 "foo 1.0.1 1.0.2" "bar 2.0.0 2.0.1"
	tag polkadot-stable2609-2-rc2 p2
	plan p3 "foo 1.0.1 1.0.2" "bar 2.0.0 2.0.1" "baz 0.1.0 0.2.0"
}

# A new line before its first release:
#   base - p1 (polkadot-stable2609-rc1) - p2 (tip, not tagged)
new_line() {
	new_case
	change base
	plan p1 "foo 1.0.0 2.0.0" "bar 2.0.0 2.0.0"
	tag polkadot-stable2609-rc1 p1
	plan p2 "foo 1.0.0 2.0.0" "bar 2.0.0 3.0.0"
}

# --- runner ------------------------------------------------------------------

# Runs a snippet in the repository with the library sourced.
run() { # run <bash snippet>
	local -a env=(
		"HOME=${HOME}"
		"PATH=${case_dir}/bin:${PATH}"
		"FAKE_GH_FIXTURES=${case_dir}/fixtures"
		"FAKE_CURL_FIXTURES=${case_dir}/index"
	)
	[[ -z "$bot_id" ]] || env+=("RELEASE_AUTOMATION_APP_BOT_ID=${bot_id}")
	(
		cd "${case_dir}/repo" &&
			env -i "${env[@]}" bash -c "set -uo pipefail; . '${lib}'; $1"
	) >"${case_dir}/stdout" 2>"${case_dir}/stderr"
}

ok() {
	passes=$((passes + 1))
	echo "ok    - $1"
}

not_ok() {
	failures=$((failures + 1))
	echo "FAIL  - $1"
	echo "        $2"
	sed 's/^/        | /' "${case_dir}/stderr"
}

# expect <name> <snippet> <expected last line of its output>
expect() {
	local name=$1 want=$3 got
	if ! run "$2"; then
		not_ok "$name" "expected it to succeed, it failed"
	else
		got=$(tail -n 1 "${case_dir}/stdout")
		if [[ "$got" == "$want" ]]; then
			ok "$name"
		else
			not_ok "$name" "expected '${want}', got '${got}'"
		fi
	fi
}

# expect_fail <name> <snippet> <expected ::error title>
expect_fail() {
	local name=$1 title=$3
	if run "$2"; then
		not_ok "$name" "expected it to fail with '${title}', it succeeded: $(tail -n 1 "${case_dir}/stdout")"
	elif ! grep -qF "::error title=${title}::" "${case_dir}/stderr"; then
		not_ok "$name" "expected error title '${title}'"
	else
		ok "$name"
	fi
}

# expect_calls <name> <calls file> <"none" | text one call must contain>
expect_calls() {
	local name=$1 file=$2 want=$3
	if [[ "$want" == none ]]; then
		if [[ -s "$file" ]]; then
			not_ok "$name" "expected no call, got: $(tr '\n' ' ' <"$file")"
		else
			ok "$name"
		fi
	elif grep -qF "$want" "$file"; then
		ok "$name"
	else
		not_ok "$name" "expected a call containing '${want}', got: $(tr '\n' ' ' <"$file")"
	fi
}

end_case() { rm -rf "$case_dir"; }

readonly STATE_OF_HEAD='publish_state "$(git rev-parse HEAD)" '"${CONTEXT}"
readonly BASELINE_OF_HEAD='find_published_baseline stable2609 HEAD '"${CONTEXT}"' || exit 1; echo "${BASELINE}|${BASELINE_SOURCE}|${INCOMPLETE}|${INCOMPLETE_STATE}|${LAST_FINAL_TAG}"'
readonly PLAN_START='echo "${PLAN_BASELINE}|${PLAN_REPLAN}|${PLAN_FIRST_PREPARE}"'

# --- publish_state -----------------------------------------------------------

new_case
plan p1 "foo 1.0.0 1.0.1"
tag polkadot-stable2609-rc1 p1
expect "a commit without statuses has no record" "$STATE_OF_HEAD" none
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record p1 "20 ${APP_BOT_ID} success"
expect "the release App's status is the record" "$STATE_OF_HEAD" success
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record p1 "20 ${OTHER_ID} success"
expect "a status from someone else is not a record" "$STATE_OF_HEAD" none
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record p1 "30 ${APP_BOT_ID} failure" "20 ${APP_BOT_ID} success"
expect "the newest status of the App decides" "$STATE_OF_HEAD" failure
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record p1 "30 ${OTHER_ID} failure" "20 ${APP_BOT_ID} success"
expect "a newer status from someone else does not override the App's" "$STATE_OF_HEAD" success
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record p1 "20 ${APP_BOT_ID} success release/e2e-gate" "10 ${APP_BOT_ID} success ${CONTEXT}-staging"
expect "the e2e gate verdict and the staging record are not the crates.io record" \
	"$STATE_OF_HEAD" none
expect "staging has its own record" \
	'publish_state "$(git rev-parse HEAD)" "$(publish_context staging.crates.io)"' success
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record_error_for p1 "HTTP 502"
expect_fail "an API error is not 'no record'" "$STATE_OF_HEAD" "GitHub API error"
end_case

new_case
plan p1 "foo 1.0.0 1.0.1"
record p1 "20 ${APP_BOT_ID} success"
bot_id=""
expect_fail "without the App's bot id nothing is read" "$STATE_OF_HEAD" \
	"Publish record not configured"
expect_calls "... and the API is not asked" "${case_dir}/fixtures/calls" none
end_case

new_case
expect_fail "an unknown registry has no record" 'publish_context example.org' "Unknown registry"
end_case

# --- find_published_baseline -------------------------------------------------

patch_line
expect "nothing published since the final tag: the final tag is the baseline" "$BASELINE_OF_HEAD" \
	"$(sha p0)|final tag|||polkadot-stable2609-1"
expect_calls "... and the commit of the final tag is not asked about" "${case_dir}/fixtures/calls" "$(sha p2)"
if grep -qF "$(sha p0)" "${case_dir}/fixtures/calls"; then
	not_ok "the walk stops before the final tag" "asked about $(sha p0)"
else
	ok "the walk stops before the final tag"
fi
end_case

patch_line
record p1 "20 ${APP_BOT_ID} success" "10 ${APP_BOT_ID} pending"
expect "a published rc is the baseline" "$BASELINE_OF_HEAD" "$(sha p1)|publish record|||polkadot-stable2609-1"
end_case

patch_line
record p1 "20 ${APP_BOT_ID} success"
record p2 "40 ${APP_BOT_ID} success"
expect "the newest published rc is the baseline" "$BASELINE_OF_HEAD" "$(sha p2)|publish record|||polkadot-stable2609-1"
end_case

patch_line
record p1 "20 ${APP_BOT_ID} success"
record p2 "30 ${APP_BOT_ID} pending"
expect "a publish that is still pending on a newer rc is reported" "$BASELINE_OF_HEAD" \
	"$(sha p1)|publish record|$(sha p2)|pending|polkadot-stable2609-1"
end_case

patch_line
record p1 "20 ${APP_BOT_ID} failure"
record p2 "30 ${APP_BOT_ID} success"
expect "an incomplete publish older than a completed one does not matter" "$BASELINE_OF_HEAD" \
	"$(sha p2)|publish record|||polkadot-stable2609-1"
end_case

patch_line
record p1 "20 ${APP_BOT_ID} failure"
expect "an incomplete publish is reported next to the final tag" "$BASELINE_OF_HEAD" \
	"$(sha p0)|final tag|$(sha p1)|failure|polkadot-stable2609-1"
end_case

patch_line
record p2 "20 ${OTHER_ID} success"
expect "a record from someone else publishes nothing" "$BASELINE_OF_HEAD" "$(sha p0)|final tag|||polkadot-stable2609-1"
end_case

patch_line
record p2 "20 ${APP_BOT_ID} success"
expect "looking back from an older rc does not see newer ones" \
	'find_published_baseline stable2609 '"$(sha p1)"' '"$CONTEXT"' || exit 1; echo "${BASELINE}|${BASELINE_SOURCE}"' \
	"$(sha p0)|final tag"
end_case

patch_line
record_error_for p1 "HTTP 503"
expect_fail "a failed lookup stops the search" "$BASELINE_OF_HEAD" "GitHub API error"
end_case

patch_line
expect_fail "an unknown ref stops the search" \
	'find_published_baseline stable2609 no-such-ref '"$CONTEXT"' || exit 1' "Unknown ref"
end_case

new_line
expect "a new line with nothing published has no baseline" "$BASELINE_OF_HEAD" "none|none|||"
end_case

new_line
record p1 "20 ${APP_BOT_ID} success"
expect "a new line with a published rc starts from it" "$BASELINE_OF_HEAD" "$(sha p1)|publish record|||"
end_case

new_case
change base
plan p1 "foo 1.0.0 2.0.0"
tag polkadot-stable2609-rc1 p1 lightweight
record p1 "20 ${APP_BOT_ID} success"
expect "a lightweight tag counts like an annotated one" "$BASELINE_OF_HEAD" "$(sha p1)|publish record|||"
end_case

new_case
change base
tag polkadot-stable2609 base
plan p1 "foo 1.0.0 1.0.1"
expect "a final tag from before the line had a Plan.toml is no baseline" "$BASELINE_OF_HEAD" \
	"none|none|||polkadot-stable2609"
end_case

# A tag of another line on this branch is not this line's rc: asking about its
# commit has no fixture and would fail the case.
new_case
change base
plan p1 "foo 1.0.0 2.0.0"
git -C "${case_dir}/repo" tag -a -m other polkadot-stable2606-9-rc1 "$(sha p1)"
git -C "${case_dir}/repo" tag -a -m other polkadot-stable26091-rc1 "$(sha p1)"
expect "tags of other lines are ignored" "$BASELINE_OF_HEAD" "none|none|||"
expect_calls "... without asking about their commits" "${case_dir}/fixtures/calls" none
end_case

# --- find_plan_start ---------------------------------------------------------

new_case
change base
change backport
expect "a branch without a Plan.toml is a first prepare run" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "none|false|true"
expect_calls "... which needs no publish record" "${case_dir}/fixtures/calls" none
end_case

new_case
change base
plan p0 "foo 1.0.0 1.0.1"
tag polkadot-stable2609-1 p0
change backport
expect "no plan since the last release: nothing to plan again" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "$(sha p0)|false|false"
end_case

patch_line
expect "plans merged since the last release and never published are planned again" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "$(sha p0)|true|false"
end_case

patch_line
record p2 "20 ${APP_BOT_ID} success"
expect "only the plan merged after the published rc is planned again" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "$(sha p2)|true|false"
end_case

new_case
change base
plan p0 "foo 1.0.0 1.0.1"
tag polkadot-stable2609-1 p0
plan p1 "foo 1.0.1 1.0.2"
tag polkadot-stable2609-2-rc1 p1
record p1 "20 ${APP_BOT_ID} success"
change backport
expect "a published rc followed by a backport: plan on top of it" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "$(sha p1)|false|false"
end_case

patch_line
record p1 "20 ${APP_BOT_ID} success"
expect "staging rehearsals read the staging record, not the crates.io one" \
	"find_plan_start stable2609 staging.crates.io '' || exit 1; ${PLAN_START}" "$(sha p0)|true|false"
end_case

patch_line
record p1 "20 ${APP_BOT_ID} success"
record p2 "30 ${APP_BOT_ID} failure"
expect_fail "an incomplete publish stops the prepare run" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "Crates publish did not complete"
if grep -qF "polkadot-stable2609-2-rc2" "${case_dir}/stderr" && grep -qF "baseline_ref to '$(sha p1)'" "${case_dir}/stderr"; then
	ok "... naming the rc to finish and the baseline to use otherwise"
else
	not_ok "... naming the rc to finish and the baseline to use otherwise" "tag or baseline missing from the message"
fi
end_case

new_line
expect "a new line whose plans were never published plans from scratch" \
	"find_plan_start stable2609 crates.io '' || exit 1; ${PLAN_START}" "none|true|false"
end_case

patch_line
record p2 "30 ${APP_BOT_ID} failure"
expect "baseline_ref names the plan to start from" \
	"find_plan_start stable2609 crates.io $(sha p1) || exit 1; ${PLAN_START}" "$(sha p1)|true|false"
expect_calls "... without reading the publish record" "${case_dir}/fixtures/calls" none
end_case

patch_line
expect "baseline_ref at the branch tip leaves nothing to plan again" \
	"find_plan_start stable2609 crates.io $(sha p3) || exit 1; ${PLAN_START}" "$(sha p3)|false|false"
end_case

new_line
expect "baseline_ref 'none' plans from scratch" \
	"find_plan_start stable2609 crates.io none || exit 1; ${PLAN_START}" "none|true|false"
end_case

new_case
change base
expect "baseline_ref does not hide a first prepare run" \
	"find_plan_start stable2609 crates.io none || exit 1; ${PLAN_START}" "none|false|true"
end_case

patch_line
expect_fail "baseline_ref without a Plan.toml is refused" \
	"find_plan_start stable2609 crates.io $(sha base) || exit 1" "Unusable baseline_ref"
end_case

patch_line
git -C "${case_dir}/repo" checkout -q -b side "$(sha p0)"
plan side "foo 1.0.1 9.9.9"
git -C "${case_dir}/repo" checkout -q stable2609
expect_fail "baseline_ref off the branch is refused" \
	"find_plan_start stable2609 crates.io $(sha side) || exit 1" "Unusable baseline_ref"
end_case

# --- introduced_versions -----------------------------------------------------

patch_line
expect "against a baseline: the versions bumped to that it does not have" \
	"introduced_versions $(sha p3) $(sha p0) | tr '\n' ','" "bar 2.0.1,baz 0.2.0,foo 1.0.2,"
expect "a version the baseline already has is not introduced again" \
	"introduced_versions $(sha p3) $(sha p2) | tr '\n' ','" "baz 0.2.0,"
expect "without a baseline: every version the plan bumps to" \
	"introduced_versions $(sha p1) none | tr '\n' ','" "foo 1.0.2,"
end_case

new_case
plan p0 "foo 1.0.0 1.0.1"
plan p1 "foo 1.0.1 1.0.1" "old 3.0.0 3.0.0"
expect "a crate that joins the plan without a bump is not being released" \
	"introduced_versions $(sha p1) $(sha p0) | wc -l | tr -d ' '" "0"
expect_fail "a commit without a Plan.toml fails" \
	"introduced_versions HEAD~5 none || { record_error 'No plan' 'git show failed'; exit 1; }" "No plan"
end_case

# --- versions_on_crates_io ---------------------------------------------------

new_case
index foo 1.0.1 1.0.2
index a 0.1.0
expect "versions on crates.io are printed, others are not" \
	"printf '%s\n' 'foo 1.0.2' 'foo 1.0.3' 'new-crate 0.1.0' 'a 0.1.0' | versions_on_crates_io | tr '\n' ','" \
	"a 0.1.0,foo 1.0.2,"
expect_calls "the sparse index is asked by crate path" "${case_dir}/index/calls" "https://index.crates.io/ne/w-/new-crate"
expect_calls "... with the short-name layout too" "${case_dir}/index/calls" "https://index.crates.io/1/a"
end_case

new_case
index foo 1.0.20
expect "a longer version with the same prefix is another version" \
	"echo 'foo 1.0.2' | versions_on_crates_io | wc -l | tr -d ' '" "0"
end_case

new_case
index foobar 1.0.0
expect "crate names are looked up in lower case" \
	"echo 'FooBar 1.0.0' | versions_on_crates_io | tr '\n' ','" "FooBar 1.0.0,"
expect_calls "... at the lower-case path" "${case_dir}/index/calls" "https://index.crates.io/fo/ob/foobar"
end_case

new_case
expect "an empty list asks nothing" "printf '' | versions_on_crates_io | wc -l | tr -d ' '" "0"
expect_calls "... of the registry" "${case_dir}/index/calls" none
end_case

new_case
index foo 1.0.2
index_error bar 503
expect_fail "a lookup without a clear answer fails the whole call" \
	"printf '%s\n' 'foo 1.0.2' 'bar 2.0.1' | versions_on_crates_io >/dev/null || exit 1" "Registry lookup failed"
end_case

# --- check_versions_free -----------------------------------------------------

patch_line
index foo 1.0.0 1.0.1
index bar 2.0.0
expect "planned versions that nobody took pass" \
	"check_versions_free stable2609 $(sha p2) crates.io >/dev/null || exit 1; echo free" "free"
end_case

patch_line
index foo 1.0.0 1.0.1 1.0.2
index bar 2.0.0
expect_fail "a planned version that another line published is refused" \
	"check_versions_free stable2609 $(sha p2) crates.io || exit 1" "Planned versions are taken"
if grep -qF "foo@1.0.2" "${case_dir}/stderr" && ! grep -qF "bar@" "${case_dir}/stderr"; then
	ok "... naming the taken version only"
else
	not_ok "... naming the taken version only" "expected foo@1.0.2 and no bar"
fi
end_case

patch_line
record p1 "20 ${APP_BOT_ID} success"
index foo 1.0.0 1.0.1 1.0.2
index bar 2.0.0
expect "versions an earlier rc of this line published are its own" \
	"check_versions_free stable2609 $(sha p2) crates.io >/dev/null || exit 1; echo free" "free"
end_case

patch_line
record p2 "20 ${APP_BOT_ID} failure" "10 ${APP_BOT_ID} pending"
index foo 1.0.0 1.0.1 1.0.2
expect "a publish from this commit that already started is not checked" \
	"check_versions_free stable2609 $(sha p2) crates.io >/dev/null || exit 1; echo free" "free"
expect_calls "... and the registry is not asked" "${case_dir}/index/calls" none
end_case

patch_line
record p1 "20 ${APP_BOT_ID} failure"
index foo 1.0.0 1.0.1 1.0.2
expect "after an incomplete publish of an earlier rc nothing is checked" \
	"check_versions_free stable2609 $(sha p2) crates.io || exit 1; echo free" "free"
if grep -qF "::warning title=Planned versions not checked::" "${case_dir}/stdout"; then
	ok "... and a warning says so"
else
	not_ok "... and a warning says so" "no warning in the output"
fi
end_case

patch_line
index_error foo 500
expect_fail "a registry that cannot be read fails the check" \
	"check_versions_free stable2609 $(sha p2) crates.io || exit 1" "Registry lookup failed"
end_case

patch_line
record_error_for p2 "HTTP 500"
expect_fail "a publish record that cannot be read fails the check" \
	"check_versions_free stable2609 $(sha p2) crates.io || exit 1" "GitHub API error"
end_case

new_line
tag polkadot-stable2609-rc2 p2
index foo 1.0.0
index bar 2.0.0 3.0.0
expect_fail "the first publish of a new line is checked against everything it bumps" \
	"check_versions_free stable2609 $(sha p2) crates.io || exit 1" "Planned versions are taken"
end_case

# A rehearsal: the rc was published to crates.io for real (its record says so),
# and is now published to staging, whose own record is empty.
patch_line
record p2 "20 ${APP_BOT_ID} success"
index foo 1.0.0 1.0.1 1.0.2
expect_fail "staging is checked against the staging record" \
	"check_versions_free stable2609 $(sha p2) staging.crates.io || exit 1" "Planned versions are taken"
expect_calls "... and against crates.io, where parity-publish looks" "${case_dir}/index/calls" "https://index.crates.io/3/f/foo"
if grep -qF "staging" "${case_dir}/index/calls"; then
	not_ok "the staging index is never asked" "asked: $(tr '\n' ' ' <"${case_dir}/index/calls")"
else
	ok "the staging index is never asked"
fi
end_case

patch_line
record p2 "20 ${APP_BOT_ID} pending ${CONTEXT}-staging"
index foo 1.0.0 1.0.1 1.0.2
expect "a staging publish that already started is not checked" \
	"check_versions_free stable2609 $(sha p2) staging.crates.io >/dev/null || exit 1; echo free" "free"
end_case

echo
echo "${passes} passed, ${failures} failed"
((failures == 0))
